{
  "per_column": [
    {
      "name": "interaction_modality_type",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.72,
      "hallucination_observed": true,
      "rationale": "A genuine grouping axis (sync/async format) relevant to satisfaction drivers. Mostly grounded: ED-0001 mentions live whiteboard sharing (sync) so mixed_sync_async is defensible; ED-0004 recorded_lecture is direct. But ED-0002 'live_discussion' is weakly supported (text describes running labs, not discussion) and ED-0005 emphasizes silent live sessions, plausibly live but modality inference is somewhat loose."
    },
    {
      "name": "hands_on_lab_access",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.78,
      "hallucination_observed": true,
      "rationale": "Useful for lab-dependent subjects and explains dissatisfaction in hands-on courses; large not_applicable share is appropriate for silent rows. ED-0002 home_materials (kitchen-chemistry kits) is well grounded. ED-0003 'equipment_unavailable' is an overreach: the reading complaint is platform/isolation, not lab equipment, so this value is invented for that row."
    },
    {
      "name": "teacher_pacing_fit",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.82,
      "hallucination_observed": false,
      "rationale": "Directly relevant driver; pacing complaints are central to the query. ED-0001 misaligned_pace (teacher 'three problems ahead') and ED-0004 student_paced_flexible ('pause at my own pace') are strongly grounded. Other labels are reasonable inferences, none clearly contradicted."
    },
    {
      "name": "peer_interaction_presence",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.8,
      "hallucination_observed": false,
      "rationale": "Peer interaction is an explicitly cited satisfaction factor (ED-0003 'zero peer interaction', ED-0005 'silent chat'), making this a strong analytical axis. Values track the text well; ED-0002 strong_community_building is a mild inference from engagement but defensible."
    },
    {
      "name": "teacher_pedagogical_innovation",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.78,
      "hallucination_observed": false,
      "rationale": "Distinct axis capturing teacher adaptation, useful for explaining variance across teachers. ED-0002 high_adaptation_creative ('forced me to be more creative') and ED-0004 documentary clips (moderate) are grounded. ED-0005 'minimal_adaptation' is a reasonable read of a frustrated teacher. Slightly subjective but warranted."
    },
    {
      "name": "subject_medium_alignment",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.68,
      "hallucination_observed": true,
      "rationale": "Conceptually valuable for tying subject to remote fit. But several values misfire: ED-0001 algebra labeled 'poor_fit_hands_on' (algebra is not hands-on) and ED-0005 essay/discussion class labeled 'poor_fit_hands_on' contradicts the discourse-heavy nature of the subject. ED-0004 strong_fit_discourse_heavy (history) is correct. Groundedness reduced by these misclassifications."
    },
    {
      "name": "developmental_stage_impact",
      "analytical_usefulness": 0.83,
      "source_groundedness": 0.82,
      "hallucination_observed": false,
      "rationale": "Age/developmental stage is a plausible driver of why younger learners struggle; supports group-level analysis. Grounded where age cues exist: ED-0002 'seventh graders', ED-0003 'second grader' -> early_primary_K2, ED-0005 'juniors' -> secondary. Overlaps partly with existing grade_level column but adds a developmental-capability interpretation, so not merely redundant."
    }
  ],
  "analytical_usefulness": 0.83,
  "source_groundedness": 0.76,
  "rationale": "The added columns collectively give strong, distinct analytical axes (modality, pacing, peer interaction, teacher adaptation, developmental stage, lab access, subject fit), all directly relevant to diagnosing why satisfaction is low and which factors drive it. None are near-constant or trivially redundant, though developmental_stage_impact partially overlaps grade_level while still adding interpretive leverage. Groundedness is generally sound for rows with explicit cues, but there are notable hallucinated/over-confident assignments: subject_medium_alignment mislabels non-hands-on subjects as 'poor_fit_hands_on', hands_on_lab_access invents 'equipment_unavailable' for a reading complaint, and some modality labels are loosely inferred. These lower but do not disqualify groundedness."
}
